def seed_source_profiles(apps, schema_editor):
    PollingProfile = apps.get_model("listings", "PollingProfile")
    SourcePollingProfile = apps.get_model("listings", "SourcePollingProfile")
    defaults = {
        "avito": "avito_default",
        "cian": "cian_default",
        "domclick": "domclick_default",
    }
    for source, code in defaults.items():
        PollingProfile.objects.filter(code=code).update(mode="all")
        profile = PollingProfile.objects.filter(code=code, source=source, enabled=True, route__enabled=True).first()
        if profile:
            SourcePollingProfile.objects.update_or_create(
                source=source, defaults={"profile": profile, "enabled": True},
            )


def unseed_source_profiles(apps, schema_editor):
    PollingProfile = apps.get_model("listings", "PollingProfile")
    SourcePollingProfile = apps.get_model("listings", "SourcePollingProfile")
    SourcePollingProfile.objects.all().delete()
    for code in ("avito_default", "cian_default", "domclick_default"):
        PollingProfile.objects.filter(code=code).update(mode="fast")


